    """Write a function that returns true if the given number is the multiplication of 3 prime numbers
    and false otherwise.
    Knowing that (a) is less then 100. 
    Example:
    is_multiply_prime(30) == True
    30 = 2 * 3 * 5
    """
    def is_prime(n):
        if n < 2:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False
        for i in range(3, int(n**0.5) + 1, 2):
            if n % i == 0:
                return False
        return True

    primes = [p for p in range(2, a + 1) if is_prime(p)]

    # We need to find if there exist three primes p1, p2, p3 such that p1 * p2 * p3 == a
    # Since a < 100, we can use nested loops
    for i in range(len(primes)):
        p1 = primes[i]
        if p1 * p1 * p1 > a:
            break
        for j in range(i, len(primes)):
            p2 = primes[j]
            if p1 * p2 * p2 > a:
                break
            # Calculate the third number needed
            needed = a // (p1 * p2)
            if p1 * p2 * p2 > a:
                break
            if p1 * p2 > a:
                break
            if p1 * p2 > a // 2:  # Optimization: if p1*p2 > a/2, then p3 must be 1 or 2, but p3 must be prime >= 2
                continue
            if a % (p1 * p2) != 0:
                continue
            p3 = needed
            if p3 < 2:
                continue
            if is_prime(p3):
                return True
    return False
